BEGIN;

-- Debit one account, capturing the new balance
UPDATE accounts
SET balance = balance - 100
WHERE account_id = 1 AND balance >= 100
RETURNING account_id, balance;

-- Credit the other account
UPDATE accounts
SET balance = balance + 100
WHERE account_id = 2
RETURNING account_id, balance;

-- Inspect RETURNING output and the affected row counts.
-- If the debit affected 0 rows (insufficient funds), abort:
--   ROLLBACK;
-- Otherwise commit both changes atomically:
COMMIT;
